fn id(map:&[i32],h:H)->i32 { if h==NONE {0} else {map.get(h as usize).copied().unwrap_or(-1)} }
fn edge(map:&[i32],h:H)->i32 { if h==NONE {0} else {let n=id(map,h>>1);if n<0 {-1} else {n*2+(h&1) as i32}} }
